<?php
defined('ABSPATH')||exit; class CFP_Download_Handler{public function hooks():void{add_action('init',array($this,'handle'));} public function handle():void{if(empty($_GET['cfp_download'])) return; $file_id=absint($_GET['cfp_download']); $order_id=absint($_GET['order_id']??0); $email=sanitize_email(wp_unslash($_GET['email']??'')); $exp=absint($_GET['expires']??0); $token=sanitize_text_field(wp_unslash($_GET['token']??'')); if($exp<time()||!hash_equals(CFP_Security::token(array($file_id,$order_id,$email,$exp)),$token)||(new CFP_File_Access())->allowed($file_id,$order_id,$email)===false){status_header(403); exit('Access denied');} do_action('cfp_file_downloaded',$file_id,$order_id,$email);}}
